window.__code__ = window.__code__ || {};
window.__code__["app-service-session-py"] = {"code_id": "app-service-session-py", "kind": "src", "title": "_session.py", "source_path": "agentscope/src/agentscope/app/_service/_session.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;Cross-resource session lifecycle service.</span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">Owns the <span class=\"c-str\">&quot;stop in-flight runs + delete records + drop bus state&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\">cascades that ``DELETE /sessions/{sid}``, ``DELETE /agents/{aid}``,</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\">``DELETE /schedules/{sid}`` <span class=\"c-kw\">and</span> the agent-facing</span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\">:<span class=\"c-kw\">class</span>:`~agentscope.app._tools.TeamDelete` /</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\">:<span class=\"c-kw\">class</span>:`~agentscope.app._manager._scheduler._tools.ScheduleDelete`</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\">tools all share.</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\">Layering</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">========</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">Methods deliberately delegate down the cascade so the bus-touching</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">logic lives <span class=\"c-kw\">in</span> exactly one place — :meth:`delete_session`. Higher-level</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">methods only orchestrate which sessions to delete, then ask storage</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\">to clean its own non-session scope (records, indexes, back-refs).</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">::</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">    delete_session    ← atomic: cancel run, storage.delete_session,</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">                        bus.session_purge</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\">        │</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    delete_team       → service.delete_agent per worker</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">                      → storage.delete_team    (record + leader detach)</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">        │</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    delete_agent      → service.delete_session per session</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">                      → service.delete_schedule per owned schedule</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">                      → storage.delete_agent   (agent record + team back-refs)</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">        │</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    delete_schedule   → service.delete_session per spawned session</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">                      → storage.delete_schedule (schedule record + indexes)</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">Storage&<span class=\"c-com\">#x27;s own internal cascades (e.g.</span></span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">``storage.delete_agent`` re-iterating sessions) become idempotent</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">no-ops because the records are already gone — they still execute, but</span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">do no work <span class=\"c-kw\">and</span> never touch the bus, so the storage layer stays</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">unaware of the message bus.</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">Separation of concerns</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">======================</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">Storage <span class=\"c-kw\">and</span> message bus are treated <span class=\"c-kw\">as</span> distinct backends — they may</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">live <span class=\"c-kw\">in</span> different databases <span class=\"c-kw\">in</span> the future. The service <span class=\"c-kw\">is</span> the **only**</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">component that touches both <span class=\"c-kw\">in</span> the same call. Storage code never</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">imports the bus; bus code never imports storage.</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\"><span class=\"c-kw\">from</span> enum <span class=\"c-kw\">import</span> StrEnum</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..message_bus <span class=\"c-kw\">import</span> MessageBus, MessageBusKeys</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..storage <span class=\"c-kw\">import</span> StorageBase</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..storage._utils <span class=\"c-kw\">import</span> _ensure_team_members</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._session_projection <span class=\"c-kw\">import</span> SessionProjection</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ._projectors <span class=\"c-kw\">import</span> SubagentHitlProjector</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..._logging <span class=\"c-kw\">import</span> logger</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ...message <span class=\"c-kw\">import</span> ToolCallState</span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\"><span class=\"c-kw\">class</span> SessionStatus(StrEnum):</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;The high-level status of a session, unifying cluster liveness</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">    (<span class=\"c-kw\">from</span> the message bus) <span class=\"c-kw\">with</span> the durable tool-call parking state</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">    (<span class=\"c-kw\">from</span> the persisted :<span class=\"c-kw\">class</span>:`~agentscope.state.AgentState.context`).</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">    Exactly one value applies at any moment — the frontend renders a</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">    single indicator without having to reconcile multiple boolean</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">    flags.</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">    Precedence: ``RUNNING`` <span class=\"c-kw\">is</span> decided first <span class=\"c-kw\">from</span> the distributed</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">    session-run lock; only when the session <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> held by any worker</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">    do the ``AWAITING_*`` / ``IDLE`` values (derived <span class=\"c-kw\">from</span> the stored</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">    context tail) apply. This ordering reflects the ground-truth</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">    hierarchy — <span class=\"c-kw\">while</span> a worker owns the run, the live <span class=\"c-kw\">in</span>-memory state</span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">    supersedes the persisted snapshot, which <span class=\"c-kw\">is</span> by definition stale</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">    until the run yields.</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">    Values:</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">        - ``RUNNING``: a worker somewhere <span class=\"c-kw\">in</span> the cluster currently</span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">          holds the session&<span class=\"c-com\">#x27;s run lease on the message bus.</span></span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">        - ``IDLE``: no worker <span class=\"c-kw\">is</span> running the session, <span class=\"c-kw\">and</span> its</span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">          persisted context <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> parked on any pending tool call.</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">        - ``AWAITING_PERMISSION``: no worker <span class=\"c-kw\">is</span> running the session,</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">          <span class=\"c-kw\">and</span> the persisted context tail has at least one tool call</span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">          waiting <span class=\"c-kw\">for</span> user permission confirmation (HITL).</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">        - ``AWAITING_EXTERNAL_RESULT``: no worker <span class=\"c-kw\">is</span> running the</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">          session, <span class=\"c-kw\">and</span> the persisted context tail has at least one</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">          tool call dispatched to an external executor <span class=\"c-kw\">and</span> awaiting</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">          its result (<span class=\"c-kw\">with</span> no peer awaiting permission).</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">    RUNNING = <span class=\"c-str\">&quot;running&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">    IDLE = <span class=\"c-str\">&quot;idle&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">    AWAITING_PERMISSION = <span class=\"c-str\">&quot;awaiting_permission&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">    AWAITING_EXTERNAL_RESULT = <span class=\"c-str\">&quot;awaiting_external_result&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\"><span class=\"c-kw\">class</span> SessionService:</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Cancel <span class=\"c-kw\">in</span>-flight chat runs <span class=\"c-kw\">and</span> cascade-delete related records.</span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">    The cancel side broadcasts via</span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">    :meth:`MessageBus.session_publish_cancel`, then polls</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">    :meth:`MessageBus.session_is_running` until the run-lock clears <span class=\"c-kw\">or</span></span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">    a timeout expires — so the implementation <span class=\"c-kw\">is</span> multi-process <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">    multi-node by construction.</span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">    Args:</span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">        storage (`StorageBase`):</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\">            Persistent storage backend. Owns durable records <span class=\"c-kw\">and</span> their</span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\">            cascades among themselves.</span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">        message_bus (`MessageBus`):</span></div>\n<div class=\"c-line\" data-line=\"111\"><span class=\"c-no\">111</span><span class=\"c-src\">            Live message bus. Owns transient per-session state (events</span></div>\n<div class=\"c-line\" data-line=\"112\"><span class=\"c-no\">112</span><span class=\"c-src\">            log, inbox, run-lock, cancel channel).</span></div>\n<div class=\"c-line\" data-line=\"113\"><span class=\"c-no\">113</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"114\"><span class=\"c-no\">114</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"115\"><span class=\"c-no\">115</span><span class=\"c-src\">    _CANCEL_POLL_INTERVAL_SECS: float = 0.1</span></div>\n<div class=\"c-line\" data-line=\"116\"><span class=\"c-no\">116</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Interval between :meth:`MessageBus.session_is_running` polls</span></div>\n<div class=\"c-line\" data-line=\"117\"><span class=\"c-no\">117</span><span class=\"c-src\">    <span class=\"c-kw\">while</span> waiting <span class=\"c-kw\">for</span> a cancelled run to release its distributed</span></div>\n<div class=\"c-line\" data-line=\"118\"><span class=\"c-no\">118</span><span class=\"c-src\">    run-lock.<span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"119\"><span class=\"c-no\">119</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"120\"><span class=\"c-no\">120</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> __init__(</span></div>\n<div class=\"c-line\" data-line=\"121\"><span class=\"c-no\">121</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"122\"><span class=\"c-no\">122</span><span class=\"c-src\">        storage: StorageBase,</span></div>\n<div class=\"c-line\" data-line=\"123\"><span class=\"c-no\">123</span><span class=\"c-src\">        message_bus: MessageBus,</span></div>\n<div class=\"c-line\" data-line=\"124\"><span class=\"c-no\">124</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"125\"><span class=\"c-no\">125</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Bind dependencies.</span></div>\n<div class=\"c-line\" data-line=\"126\"><span class=\"c-no\">126</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"127\"><span class=\"c-no\">127</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"128\"><span class=\"c-no\">128</span><span class=\"c-src\">            storage (`StorageBase`): Persistent storage backend.</span></div>\n<div class=\"c-line\" data-line=\"129\"><span class=\"c-no\">129</span><span class=\"c-src\">            message_bus (`MessageBus`): Live message bus.</span></div>\n<div class=\"c-line\" data-line=\"130\"><span class=\"c-no\">130</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"131\"><span class=\"c-no\">131</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._storage = storage</span></div>\n<div class=\"c-line\" data-line=\"132\"><span class=\"c-no\">132</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._bus = message_bus</span></div>\n<div class=\"c-line\" data-line=\"133\"><span class=\"c-no\">133</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._projection = SessionProjection(message_bus)</span></div>\n<div class=\"c-line\" data-line=\"134\"><span class=\"c-no\">134</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"135\"><span class=\"c-no\">135</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"136\"><span class=\"c-no\">136</span><span class=\"c-src\">    <span class=\"c-com\"># Status</span></span></div>\n<div class=\"c-line\" data-line=\"137\"><span class=\"c-no\">137</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"138\"><span class=\"c-no\">138</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"139\"><span class=\"c-no\">139</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> get_session_status(</span></div>\n<div class=\"c-line\" data-line=\"140\"><span class=\"c-no\">140</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"141\"><span class=\"c-no\">141</span><span class=\"c-src\">        user_id: str,</span></div>\n<div class=\"c-line\" data-line=\"142\"><span class=\"c-no\">142</span><span class=\"c-src\">        agent_id: str,</span></div>\n<div class=\"c-line\" data-line=\"143\"><span class=\"c-no\">143</span><span class=\"c-src\">        session_id: str,</span></div>\n<div class=\"c-line\" data-line=\"144\"><span class=\"c-no\">144</span><span class=\"c-src\">    ) -&gt; SessionStatus | <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"145\"><span class=\"c-no\">145</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Return the unified :<span class=\"c-kw\">class</span>:`SessionStatus` <span class=\"c-kw\">for</span> a session.</span></div>\n<div class=\"c-line\" data-line=\"146\"><span class=\"c-no\">146</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"147\"><span class=\"c-no\">147</span><span class=\"c-src\">        The status collapses two orthogonal signals into a single</span></div>\n<div class=\"c-line\" data-line=\"148\"><span class=\"c-no\">148</span><span class=\"c-src\">        four-valued enum:</span></div>\n<div class=\"c-line\" data-line=\"149\"><span class=\"c-no\">149</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"150\"><span class=\"c-no\">150</span><span class=\"c-src\">        - cluster liveness comes <span class=\"c-kw\">from</span> the distributed session-run lock</span></div>\n<div class=\"c-line\" data-line=\"151\"><span class=\"c-no\">151</span><span class=\"c-src\">          on the shared message bus (Redis <span class=\"c-kw\">in</span> production) — the answer</span></div>\n<div class=\"c-line\" data-line=\"152\"><span class=\"c-no\">152</span><span class=\"c-src\">          <span class=\"c-kw\">is</span> cluster-wide, so any worker <span class=\"c-kw\">in</span> the deployment holding the</span></div>\n<div class=\"c-line\" data-line=\"153\"><span class=\"c-no\">153</span><span class=\"c-src\">          lease yields ``RUNNING`` regardless of which API replica</span></div>\n<div class=\"c-line\" data-line=\"154\"><span class=\"c-no\">154</span><span class=\"c-src\">          serves the caller;</span></div>\n<div class=\"c-line\" data-line=\"155\"><span class=\"c-no\">155</span><span class=\"c-src\">        - the parked state (``AWAITING_PERMISSION`` /</span></div>\n<div class=\"c-line\" data-line=\"156\"><span class=\"c-no\">156</span><span class=\"c-src\">          ``AWAITING_EXTERNAL_RESULT`` / ``IDLE``) <span class=\"c-kw\">is</span> derived <span class=\"c-kw\">from</span> the</span></div>\n<div class=\"c-line\" data-line=\"157\"><span class=\"c-no\">157</span><span class=\"c-src\">          persisted ``AgentState.context`` tail, <span class=\"c-kw\">and</span> only applies when</span></div>\n<div class=\"c-line\" data-line=\"158\"><span class=\"c-no\">158</span><span class=\"c-src\">          no worker owns the run.</span></div>\n<div class=\"c-line\" data-line=\"159\"><span class=\"c-no\">159</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"160\"><span class=\"c-no\">160</span><span class=\"c-src\">        The ``RUNNING`` check <span class=\"c-kw\">is</span> performed **before** loading the</span></div>\n<div class=\"c-line\" data-line=\"161\"><span class=\"c-no\">161</span><span class=\"c-src\">        persisted context: <span class=\"c-kw\">while</span> a worker owns the run, the live</span></div>\n<div class=\"c-line\" data-line=\"162\"><span class=\"c-no\">162</span><span class=\"c-src\">        <span class=\"c-kw\">in</span>-memory state supersedes the stored snapshot, <span class=\"c-kw\">and</span> the parked</span></div>\n<div class=\"c-line\" data-line=\"163\"><span class=\"c-no\">163</span><span class=\"c-src\">        derivation would be stale. This also saves a storage round-trip</span></div>\n<div class=\"c-line\" data-line=\"164\"><span class=\"c-no\">164</span><span class=\"c-src\">        <span class=\"c-kw\">in</span> the hot ``RUNNING`` case.</span></div>\n<div class=\"c-line\" data-line=\"165\"><span class=\"c-no\">165</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"166\"><span class=\"c-no\">166</span><span class=\"c-src\">        .. note::</span></div>\n<div class=\"c-line\" data-line=\"167\"><span class=\"c-no\">167</span><span class=\"c-src\">            The run lease auto-expires after</span></div>\n<div class=\"c-line\" data-line=\"168\"><span class=\"c-no\">168</span><span class=\"c-src\">            ``MessageBusKeys.SESSION_RUN_TTL_SECS`` <span class=\"c-kw\">and</span> <span class=\"c-kw\">is</span> refreshed by</span></div>\n<div class=\"c-line\" data-line=\"169\"><span class=\"c-no\">169</span><span class=\"c-src\">            the owning worker <span class=\"c-kw\">while</span> it <span class=\"c-kw\">is</span> actively producing events, so</span></div>\n<div class=\"c-line\" data-line=\"170\"><span class=\"c-no\">170</span><span class=\"c-src\">            a crashed worker&<span class=\"c-com\">#x27;s session flips out of ``RUNNING`` on</span></span></div>\n<div class=\"c-line\" data-line=\"171\"><span class=\"c-no\">171</span><span class=\"c-src\">            lease expiry.</span></div>\n<div class=\"c-line\" data-line=\"172\"><span class=\"c-no\">172</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"173\"><span class=\"c-no\">173</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"174\"><span class=\"c-no\">174</span><span class=\"c-src\">            user_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"175\"><span class=\"c-no\">175</span><span class=\"c-src\">                The authenticated user id (ownership check).</span></div>\n<div class=\"c-line\" data-line=\"176\"><span class=\"c-no\">176</span><span class=\"c-src\">            agent_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"177\"><span class=\"c-no\">177</span><span class=\"c-src\">                The agent that owns the session (ownership check).</span></div>\n<div class=\"c-line\" data-line=\"178\"><span class=\"c-no\">178</span><span class=\"c-src\">            session_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"179\"><span class=\"c-no\">179</span><span class=\"c-src\">                The session to probe.</span></div>\n<div class=\"c-line\" data-line=\"180\"><span class=\"c-no\">180</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"181\"><span class=\"c-no\">181</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"182\"><span class=\"c-no\">182</span><span class=\"c-src\">            `SessionStatus | <span class=\"c-kw\">None</span>`:</span></div>\n<div class=\"c-line\" data-line=\"183\"><span class=\"c-no\">183</span><span class=\"c-src\">                The unified status, <span class=\"c-kw\">or</span> ``<span class=\"c-kw\">None</span>`` <span class=\"c-kw\">if</span> the session does</span></div>\n<div class=\"c-line\" data-line=\"184\"><span class=\"c-no\">184</span><span class=\"c-src\">                <span class=\"c-kw\">not</span> exist <span class=\"c-kw\">or</span> <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> owned by the user.</span></div>\n<div class=\"c-line\" data-line=\"185\"><span class=\"c-no\">185</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"186\"><span class=\"c-no\">186</span><span class=\"c-src\">        <span class=\"c-com\"># RUNNING is checked first: while a worker owns the lease, the</span></span></div>\n<div class=\"c-line\" data-line=\"187\"><span class=\"c-no\">187</span><span class=\"c-src\">        <span class=\"c-com\"># persisted context is by definition a stale snapshot, and we</span></span></div>\n<div class=\"c-line\" data-line=\"188\"><span class=\"c-no\">188</span><span class=\"c-src\">        <span class=\"c-com\"># save a storage round-trip.</span></span></div>\n<div class=\"c-line\" data-line=\"189\"><span class=\"c-no\">189</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._bus.is_locked(</span></div>\n<div class=\"c-line\" data-line=\"190\"><span class=\"c-no\">190</span><span class=\"c-src\">            MessageBusKeys.session_lock(session_id),</span></div>\n<div class=\"c-line\" data-line=\"191\"><span class=\"c-no\">191</span><span class=\"c-src\">        ):</span></div>\n<div class=\"c-line\" data-line=\"192\"><span class=\"c-no\">192</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> SessionStatus.RUNNING</span></div>\n<div class=\"c-line\" data-line=\"193\"><span class=\"c-no\">193</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"194\"><span class=\"c-no\">194</span><span class=\"c-src\">        session = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.get_session(</span></div>\n<div class=\"c-line\" data-line=\"195\"><span class=\"c-no\">195</span><span class=\"c-src\">            user_id,</span></div>\n<div class=\"c-line\" data-line=\"196\"><span class=\"c-no\">196</span><span class=\"c-src\">            agent_id,</span></div>\n<div class=\"c-line\" data-line=\"197\"><span class=\"c-no\">197</span><span class=\"c-src\">            session_id,</span></div>\n<div class=\"c-line\" data-line=\"198\"><span class=\"c-no\">198</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"199\"><span class=\"c-no\">199</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> session <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"200\"><span class=\"c-no\">200</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"201\"><span class=\"c-no\">201</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"202\"><span class=\"c-no\">202</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">self</span>._derive_parked_status(session.state.context)</span></div>\n<div class=\"c-line\" data-line=\"203\"><span class=\"c-no\">203</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"204\"><span class=\"c-no\">204</span><span class=\"c-src\">    @staticmethod</span></div>\n<div class=\"c-line\" data-line=\"205\"><span class=\"c-no\">205</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _derive_parked_status(context: list) -&gt; SessionStatus:</span></div>\n<div class=\"c-line\" data-line=\"206\"><span class=\"c-no\">206</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Derive the parked :<span class=\"c-kw\">class</span>:`SessionStatus` <span class=\"c-kw\">from</span> a persisted</span></div>\n<div class=\"c-line\" data-line=\"207\"><span class=\"c-no\">207</span><span class=\"c-src\">        ``AgentState.context``.</span></div>\n<div class=\"c-line\" data-line=\"208\"><span class=\"c-no\">208</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"209\"><span class=\"c-no\">209</span><span class=\"c-src\">        Only the tail assistant message <span class=\"c-kw\">is</span> inspected — a paused reply</span></div>\n<div class=\"c-line\" data-line=\"210\"><span class=\"c-no\">210</span><span class=\"c-src\">        can only park pending tool calls at the very end of the</span></div>\n<div class=\"c-line\" data-line=\"211\"><span class=\"c-no\">211</span><span class=\"c-src\">        context. ``AWAITING_PERMISSION`` wins over</span></div>\n<div class=\"c-line\" data-line=\"212\"><span class=\"c-no\">212</span><span class=\"c-src\">        ``AWAITING_EXTERNAL_RESULT`` when both appear on the tail: no</span></div>\n<div class=\"c-line\" data-line=\"213\"><span class=\"c-no\">213</span><span class=\"c-src\">        submitted call can complete <span class=\"c-kw\">while</span> a peer <span class=\"c-kw\">is</span> still awaiting user</span></div>\n<div class=\"c-line\" data-line=\"214\"><span class=\"c-no\">214</span><span class=\"c-src\">        confirmation, so the caller-visible status <span class=\"c-kw\">is</span> dominated by the</span></div>\n<div class=\"c-line\" data-line=\"215\"><span class=\"c-no\">215</span><span class=\"c-src\">        blocker.</span></div>\n<div class=\"c-line\" data-line=\"216\"><span class=\"c-no\">216</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"217\"><span class=\"c-no\">217</span><span class=\"c-src\">        Callers must first ensure the session <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> currently held by</span></div>\n<div class=\"c-line\" data-line=\"218\"><span class=\"c-no\">218</span><span class=\"c-src\">        any worker (see :attr:`SessionStatus.RUNNING`) — <span class=\"c-kw\">while</span> a worker</span></div>\n<div class=\"c-line\" data-line=\"219\"><span class=\"c-no\">219</span><span class=\"c-src\">        owns the run, the live <span class=\"c-kw\">in</span>-memory state supersedes the persisted</span></div>\n<div class=\"c-line\" data-line=\"220\"><span class=\"c-no\">220</span><span class=\"c-src\">        snapshot <span class=\"c-kw\">and</span> this function&<span class=\"c-com\">#x27;s answer is by definition stale.</span></span></div>\n<div class=\"c-line\" data-line=\"221\"><span class=\"c-no\">221</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"222\"><span class=\"c-no\">222</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"223\"><span class=\"c-no\">223</span><span class=\"c-src\">            context (`list[Msg]`):</span></div>\n<div class=\"c-line\" data-line=\"224\"><span class=\"c-no\">224</span><span class=\"c-src\">                The persisted ``AgentState.context`` list.</span></div>\n<div class=\"c-line\" data-line=\"225\"><span class=\"c-no\">225</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"226\"><span class=\"c-no\">226</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"227\"><span class=\"c-no\">227</span><span class=\"c-src\">            `SessionStatus`:</span></div>\n<div class=\"c-line\" data-line=\"228\"><span class=\"c-no\">228</span><span class=\"c-src\">                One of ``AWAITING_PERMISSION``,</span></div>\n<div class=\"c-line\" data-line=\"229\"><span class=\"c-no\">229</span><span class=\"c-src\">                ``AWAITING_EXTERNAL_RESULT``, <span class=\"c-kw\">or</span> ``IDLE``.</span></div>\n<div class=\"c-line\" data-line=\"230\"><span class=\"c-no\">230</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"231\"><span class=\"c-no\">231</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> context:</span></div>\n<div class=\"c-line\" data-line=\"232\"><span class=\"c-no\">232</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> SessionStatus.IDLE</span></div>\n<div class=\"c-line\" data-line=\"233\"><span class=\"c-no\">233</span><span class=\"c-src\">        last_msg = context[-1]</span></div>\n<div class=\"c-line\" data-line=\"234\"><span class=\"c-no\">234</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> last_msg.role != <span class=\"c-str\">&quot;assistant&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"235\"><span class=\"c-no\">235</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> SessionStatus.IDLE</span></div>\n<div class=\"c-line\" data-line=\"236\"><span class=\"c-no\">236</span><span class=\"c-src\">        tool_calls = last_msg.get_content_blocks(<span class=\"c-str\">&quot;tool_call&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"237\"><span class=\"c-no\">237</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> tool_calls:</span></div>\n<div class=\"c-line\" data-line=\"238\"><span class=\"c-no\">238</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> SessionStatus.IDLE</span></div>\n<div class=\"c-line\" data-line=\"239\"><span class=\"c-no\">239</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> any(tc.state == ToolCallState.ASKING <span class=\"c-kw\">for</span> tc <span class=\"c-kw\">in</span> tool_calls):</span></div>\n<div class=\"c-line\" data-line=\"240\"><span class=\"c-no\">240</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> SessionStatus.AWAITING_PERMISSION</span></div>\n<div class=\"c-line\" data-line=\"241\"><span class=\"c-no\">241</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> any(tc.state == ToolCallState.SUBMITTED <span class=\"c-kw\">for</span> tc <span class=\"c-kw\">in</span> tool_calls):</span></div>\n<div class=\"c-line\" data-line=\"242\"><span class=\"c-no\">242</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> SessionStatus.AWAITING_EXTERNAL_RESULT</span></div>\n<div class=\"c-line\" data-line=\"243\"><span class=\"c-no\">243</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> SessionStatus.IDLE</span></div>\n<div class=\"c-line\" data-line=\"244\"><span class=\"c-no\">244</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"245\"><span class=\"c-no\">245</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"246\"><span class=\"c-no\">246</span><span class=\"c-src\">    <span class=\"c-com\"># Cancel</span></span></div>\n<div class=\"c-line\" data-line=\"247\"><span class=\"c-no\">247</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"248\"><span class=\"c-no\">248</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"249\"><span class=\"c-no\">249</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> cancel_session_run(</span></div>\n<div class=\"c-line\" data-line=\"250\"><span class=\"c-no\">250</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"251\"><span class=\"c-no\">251</span><span class=\"c-src\">        session_id: str,</span></div>\n<div class=\"c-line\" data-line=\"252\"><span class=\"c-no\">252</span><span class=\"c-src\">        *,</span></div>\n<div class=\"c-line\" data-line=\"253\"><span class=\"c-no\">253</span><span class=\"c-src\">        timeout: float = 10.0,</span></div>\n<div class=\"c-line\" data-line=\"254\"><span class=\"c-no\">254</span><span class=\"c-src\">    ) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"255\"><span class=\"c-no\">255</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Broadcast a session cancel <span class=\"c-kw\">and</span> wait <span class=\"c-kw\">for</span> the chat-run lock to</span></div>\n<div class=\"c-line\" data-line=\"256\"><span class=\"c-no\">256</span><span class=\"c-src\">        clear.</span></div>\n<div class=\"c-line\" data-line=\"257\"><span class=\"c-no\">257</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"258\"><span class=\"c-no\">258</span><span class=\"c-src\">        Publishes one cancel payload on the bus&<span class=\"c-com\">#x27;s shared cancel channel,</span></span></div>\n<div class=\"c-line\" data-line=\"259\"><span class=\"c-no\">259</span><span class=\"c-src\">        unconditionally. Every process&<span class=\"c-com\">#x27;s</span></span></div>\n<div class=\"c-line\" data-line=\"260\"><span class=\"c-no\">260</span><span class=\"c-src\">        :<span class=\"c-kw\">class</span>:`~agentscope.app._manager.CancelDispatcher` reacts to the</span></div>\n<div class=\"c-line\" data-line=\"261\"><span class=\"c-no\">261</span><span class=\"c-src\">        broadcast by cancelling whatever it locally holds <span class=\"c-kw\">for</span> the</span></div>\n<div class=\"c-line\" data-line=\"262\"><span class=\"c-no\">262</span><span class=\"c-src\">        session — the chat-run asyncio task **<span class=\"c-kw\">and</span>** any background</span></div>\n<div class=\"c-line\" data-line=\"263\"><span class=\"c-no\">263</span><span class=\"c-src\">        tasks owned by that session. The publisher does <span class=\"c-kw\">not</span> need to</span></div>\n<div class=\"c-line\" data-line=\"264\"><span class=\"c-no\">264</span><span class=\"c-src\">        know which worker holds which piece.</span></div>\n<div class=\"c-line\" data-line=\"265\"><span class=\"c-no\">265</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"266\"><span class=\"c-no\">266</span><span class=\"c-src\">        After publishing, polls</span></div>\n<div class=\"c-line\" data-line=\"267\"><span class=\"c-no\">267</span><span class=\"c-src\">        :meth:`MessageBus.session_is_running` until the distributed</span></div>\n<div class=\"c-line\" data-line=\"268\"><span class=\"c-no\">268</span><span class=\"c-src\">        chat-run lock clears. Only the chat run holds a distributed</span></div>\n<div class=\"c-line\" data-line=\"269\"><span class=\"c-no\">269</span><span class=\"c-src\">        lock; BG tasks do <span class=\"c-kw\">not</span>, so this poll only waits <span class=\"c-kw\">for</span> the chat</span></div>\n<div class=\"c-line\" data-line=\"270\"><span class=\"c-no\">270</span><span class=\"c-src\">        run. Returns immediately when no chat run was active.</span></div>\n<div class=\"c-line\" data-line=\"271\"><span class=\"c-no\">271</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"272\"><span class=\"c-no\">272</span><span class=\"c-src\">        Idempotent: calling on an idle session just sends a no-op</span></div>\n<div class=\"c-line\" data-line=\"273\"><span class=\"c-no\">273</span><span class=\"c-src\">        broadcast <span class=\"c-kw\">and</span> observes a clear lock.</span></div>\n<div class=\"c-line\" data-line=\"274\"><span class=\"c-no\">274</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"275\"><span class=\"c-no\">275</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"276\"><span class=\"c-no\">276</span><span class=\"c-src\">            session_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"277\"><span class=\"c-no\">277</span><span class=\"c-src\">                The session whose chat run + BG tasks should be</span></div>\n<div class=\"c-line\" data-line=\"278\"><span class=\"c-no\">278</span><span class=\"c-src\">                cancelled.</span></div>\n<div class=\"c-line\" data-line=\"279\"><span class=\"c-no\">279</span><span class=\"c-src\">            timeout (`float`, defaults to ``10.0``):</span></div>\n<div class=\"c-line\" data-line=\"280\"><span class=\"c-no\">280</span><span class=\"c-src\">                Maximum seconds to wait <span class=\"c-kw\">for</span> the chat-run lock to</span></div>\n<div class=\"c-line\" data-line=\"281\"><span class=\"c-no\">281</span><span class=\"c-src\">                release. On timeout the method returns ``<span class=\"c-kw\">False</span>`` so</span></div>\n<div class=\"c-line\" data-line=\"282\"><span class=\"c-no\">282</span><span class=\"c-src\">                callers can proceed (e.g. <span class=\"c-kw\">with</span> cascade delete) instead</span></div>\n<div class=\"c-line\" data-line=\"283\"><span class=\"c-no\">283</span><span class=\"c-src\">                of hanging on a process that may have died.</span></div>\n<div class=\"c-line\" data-line=\"284\"><span class=\"c-no\">284</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"285\"><span class=\"c-no\">285</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"286\"><span class=\"c-no\">286</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"287\"><span class=\"c-no\">287</span><span class=\"c-src\">                ``<span class=\"c-kw\">True</span>`` <span class=\"c-kw\">if</span> the chat-run lock was confirmed released</span></div>\n<div class=\"c-line\" data-line=\"288\"><span class=\"c-no\">288</span><span class=\"c-src\">                within ``timeout`` seconds (<span class=\"c-kw\">or</span> was never held).</span></div>\n<div class=\"c-line\" data-line=\"289\"><span class=\"c-no\">289</span><span class=\"c-src\">                ``<span class=\"c-kw\">False</span>`` <span class=\"c-kw\">if</span> the lock was still held when the timeout</span></div>\n<div class=\"c-line\" data-line=\"290\"><span class=\"c-no\">290</span><span class=\"c-src\">                expired.</span></div>\n<div class=\"c-line\" data-line=\"291\"><span class=\"c-no\">291</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"292\"><span class=\"c-no\">292</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._bus.publish(</span></div>\n<div class=\"c-line\" data-line=\"293\"><span class=\"c-no\">293</span><span class=\"c-src\">            MessageBusKeys.session_cancel_channel(),</span></div>\n<div class=\"c-line\" data-line=\"294\"><span class=\"c-no\">294</span><span class=\"c-src\">            {<span class=\"c-str\">&quot;session_id&quot;</span>: session_id},</span></div>\n<div class=\"c-line\" data-line=\"295\"><span class=\"c-no\">295</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"296\"><span class=\"c-no\">296</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"297\"><span class=\"c-no\">297</span><span class=\"c-src\">        deadline = asyncio.get_event_loop().time() + timeout</span></div>\n<div class=\"c-line\" data-line=\"298\"><span class=\"c-no\">298</span><span class=\"c-src\">        <span class=\"c-kw\">while</span> <span class=\"c-kw\">True</span>:</span></div>\n<div class=\"c-line\" data-line=\"299\"><span class=\"c-no\">299</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._bus.is_locked(</span></div>\n<div class=\"c-line\" data-line=\"300\"><span class=\"c-no\">300</span><span class=\"c-src\">                MessageBusKeys.session_lock(session_id),</span></div>\n<div class=\"c-line\" data-line=\"301\"><span class=\"c-no\">301</span><span class=\"c-src\">            ):</span></div>\n<div class=\"c-line\" data-line=\"302\"><span class=\"c-no\">302</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"303\"><span class=\"c-no\">303</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> asyncio.get_event_loop().time() &gt;= deadline:</span></div>\n<div class=\"c-line\" data-line=\"304\"><span class=\"c-no\">304</span><span class=\"c-src\">                logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"305\"><span class=\"c-no\">305</span><span class=\"c-src\">                    <span class=\"c-str\">&quot;Session %s did not release its run-lock within &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"306\"><span class=\"c-no\">306</span><span class=\"c-src\">                    <span class=\"c-str\">&quot;%.1fs after cancel; proceeding anyway.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"307\"><span class=\"c-no\">307</span><span class=\"c-src\">                    session_id,</span></div>\n<div class=\"c-line\" data-line=\"308\"><span class=\"c-no\">308</span><span class=\"c-src\">                    timeout,</span></div>\n<div class=\"c-line\" data-line=\"309\"><span class=\"c-no\">309</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"310\"><span class=\"c-no\">310</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"311\"><span class=\"c-no\">311</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> asyncio.sleep(<span class=\"c-kw\">self</span>._CANCEL_POLL_INTERVAL_SECS)</span></div>\n<div class=\"c-line\" data-line=\"312\"><span class=\"c-no\">312</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"313\"><span class=\"c-no\">313</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"314\"><span class=\"c-no\">314</span><span class=\"c-src\">    <span class=\"c-com\"># Delete cascades — every higher-level method delegates to</span></span></div>\n<div class=\"c-line\" data-line=\"315\"><span class=\"c-no\">315</span><span class=\"c-src\">    <span class=\"c-com\"># ``delete_session`` so the cancel + bus-purge logic exists in</span></span></div>\n<div class=\"c-line\" data-line=\"316\"><span class=\"c-no\">316</span><span class=\"c-src\">    <span class=\"c-com\"># exactly one place.</span></span></div>\n<div class=\"c-line\" data-line=\"317\"><span class=\"c-no\">317</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"318\"><span class=\"c-no\">318</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"319\"><span class=\"c-no\">319</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> delete_session(</span></div>\n<div class=\"c-line\" data-line=\"320\"><span class=\"c-no\">320</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"321\"><span class=\"c-no\">321</span><span class=\"c-src\">        user_id: str,</span></div>\n<div class=\"c-line\" data-line=\"322\"><span class=\"c-no\">322</span><span class=\"c-src\">        agent_id: str,</span></div>\n<div class=\"c-line\" data-line=\"323\"><span class=\"c-no\">323</span><span class=\"c-src\">        session_id: str,</span></div>\n<div class=\"c-line\" data-line=\"324\"><span class=\"c-no\">324</span><span class=\"c-src\">    ) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"325\"><span class=\"c-no\">325</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Cancel, delete <span class=\"c-kw\">and</span> bus-purge a single session.</span></div>\n<div class=\"c-line\" data-line=\"326\"><span class=\"c-no\">326</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"327\"><span class=\"c-no\">327</span><span class=\"c-src\">        This <span class=\"c-kw\">is</span> the atomic primitive — every other cascade delegates</span></div>\n<div class=\"c-line\" data-line=\"328\"><span class=\"c-no\">328</span><span class=\"c-src\">        here <span class=\"c-kw\">for</span> per-session work.</span></div>\n<div class=\"c-line\" data-line=\"329\"><span class=\"c-no\">329</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"330\"><span class=\"c-no\">330</span><span class=\"c-src\">        Steps:</span></div>\n<div class=\"c-line\" data-line=\"331\"><span class=\"c-no\">331</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"332\"><span class=\"c-no\">332</span><span class=\"c-src\">        1. Cancel any <span class=\"c-kw\">in</span>-flight run <span class=\"c-kw\">for</span> ``session_id`` (cross-process</span></div>\n<div class=\"c-line\" data-line=\"333\"><span class=\"c-no\">333</span><span class=\"c-src\">           via the bus cancel channel).</span></div>\n<div class=\"c-line\" data-line=\"334\"><span class=\"c-no\">334</span><span class=\"c-src\">        2. Delete the session record (<span class=\"c-kw\">and</span> its storage-side cascade:</span></div>\n<div class=\"c-line\" data-line=\"335\"><span class=\"c-no\">335</span><span class=\"c-src\">           message log, schedule-session index, team dissolution when</span></div>\n<div class=\"c-line\" data-line=\"336\"><span class=\"c-no\">336</span><span class=\"c-src\">           this session leads one — recursive into worker agents).</span></div>\n<div class=\"c-line\" data-line=\"337\"><span class=\"c-no\">337</span><span class=\"c-src\">        3. Purge transient bus state <span class=\"c-kw\">for</span> ``session_id`` (events log,</span></div>\n<div class=\"c-line\" data-line=\"338\"><span class=\"c-no\">338</span><span class=\"c-src\">           inbox).</span></div>\n<div class=\"c-line\" data-line=\"339\"><span class=\"c-no\">339</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"340\"><span class=\"c-no\">340</span><span class=\"c-src\">        Worker sessions that storage cascades through are picked up</span></div>\n<div class=\"c-line\" data-line=\"341\"><span class=\"c-no\">341</span><span class=\"c-src\">        here too: when this session <span class=\"c-kw\">is</span> a team leader,</span></div>\n<div class=\"c-line\" data-line=\"342\"><span class=\"c-no\">342</span><span class=\"c-src\">        ``storage.delete_session`` calls ``storage.delete_team`` →</span></div>\n<div class=\"c-line\" data-line=\"343\"><span class=\"c-no\">343</span><span class=\"c-src\">        ``storage.delete_agent`` → ``storage.delete_session`` <span class=\"c-kw\">for</span> each</span></div>\n<div class=\"c-line\" data-line=\"344\"><span class=\"c-no\">344</span><span class=\"c-src\">        worker, <span class=\"c-kw\">and</span> we mirror that on the bus side by purging worker</span></div>\n<div class=\"c-line\" data-line=\"345\"><span class=\"c-no\">345</span><span class=\"c-src\">        sessions identified up front via</span></div>\n<div class=\"c-line\" data-line=\"346\"><span class=\"c-no\">346</span><span class=\"c-src\">        :meth:`_team_worker_session_ids`.</span></div>\n<div class=\"c-line\" data-line=\"347\"><span class=\"c-no\">347</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"348\"><span class=\"c-no\">348</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"349\"><span class=\"c-no\">349</span><span class=\"c-src\">            user_id (`str`): The owner user id.</span></div>\n<div class=\"c-line\" data-line=\"350\"><span class=\"c-no\">350</span><span class=\"c-src\">            agent_id (`str`): The agent that owns the session.</span></div>\n<div class=\"c-line\" data-line=\"351\"><span class=\"c-no\">351</span><span class=\"c-src\">            session_id (`str`): The session to delete.</span></div>\n<div class=\"c-line\" data-line=\"352\"><span class=\"c-no\">352</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"353\"><span class=\"c-no\">353</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"354\"><span class=\"c-no\">354</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"355\"><span class=\"c-no\">355</span><span class=\"c-src\">                ``<span class=\"c-kw\">True</span>`` <span class=\"c-kw\">if</span> the session record existed <span class=\"c-kw\">and</span> was deleted,</span></div>\n<div class=\"c-line\" data-line=\"356\"><span class=\"c-no\">356</span><span class=\"c-src\">                ``<span class=\"c-kw\">False</span>`` otherwise. Mirrors</span></div>\n<div class=\"c-line\" data-line=\"357\"><span class=\"c-no\">357</span><span class=\"c-src\">                :meth:`StorageBase.delete_session`.</span></div>\n<div class=\"c-line\" data-line=\"358\"><span class=\"c-no\">358</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"359\"><span class=\"c-no\">359</span><span class=\"c-src\">        <span class=\"c-com\"># Identify all bus-purge targets before storage mutates anything.</span></span></div>\n<div class=\"c-line\" data-line=\"360\"><span class=\"c-no\">360</span><span class=\"c-src\">        worker_sids = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._team_worker_session_ids(</span></div>\n<div class=\"c-line\" data-line=\"361\"><span class=\"c-no\">361</span><span class=\"c-src\">            user_id,</span></div>\n<div class=\"c-line\" data-line=\"362\"><span class=\"c-no\">362</span><span class=\"c-src\">            agent_id,</span></div>\n<div class=\"c-line\" data-line=\"363\"><span class=\"c-no\">363</span><span class=\"c-src\">            session_id,</span></div>\n<div class=\"c-line\" data-line=\"364\"><span class=\"c-no\">364</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"365\"><span class=\"c-no\">365</span><span class=\"c-src\">        all_sids = [session_id, *worker_sids]</span></div>\n<div class=\"c-line\" data-line=\"366\"><span class=\"c-no\">366</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"367\"><span class=\"c-no\">367</span><span class=\"c-src\">        <span class=\"c-com\"># Clean leader-side subagent HITL projections before storage</span></span></div>\n<div class=\"c-line\" data-line=\"368\"><span class=\"c-no\">368</span><span class=\"c-src\">        <span class=\"c-com\"># cascades remove the records we need to resolve roles from.</span></span></div>\n<div class=\"c-line\" data-line=\"369\"><span class=\"c-no\">369</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._purge_subagent_hitl(user_id, agent_id, session_id)</span></div>\n<div class=\"c-line\" data-line=\"370\"><span class=\"c-no\">370</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"371\"><span class=\"c-no\">371</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._cancel_runs(all_sids)</span></div>\n<div class=\"c-line\" data-line=\"372\"><span class=\"c-no\">372</span><span class=\"c-src\">        deleted = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.delete_session(</span></div>\n<div class=\"c-line\" data-line=\"373\"><span class=\"c-no\">373</span><span class=\"c-src\">            user_id,</span></div>\n<div class=\"c-line\" data-line=\"374\"><span class=\"c-no\">374</span><span class=\"c-src\">            agent_id,</span></div>\n<div class=\"c-line\" data-line=\"375\"><span class=\"c-no\">375</span><span class=\"c-src\">            session_id,</span></div>\n<div class=\"c-line\" data-line=\"376\"><span class=\"c-no\">376</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"377\"><span class=\"c-no\">377</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._purge_bus(all_sids)</span></div>\n<div class=\"c-line\" data-line=\"378\"><span class=\"c-no\">378</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> deleted</span></div>\n<div class=\"c-line\" data-line=\"379\"><span class=\"c-no\">379</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"380\"><span class=\"c-no\">380</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> delete_team(<span class=\"c-kw\">self</span>, user_id: str, team_id: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"381\"><span class=\"c-no\">381</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Cancel, delete <span class=\"c-kw\">and</span> bus-purge a team.</span></div>\n<div class=\"c-line\" data-line=\"382\"><span class=\"c-no\">382</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"383\"><span class=\"c-no\">383</span><span class=\"c-src\">        With :meth:`StorageBase.delete_team` now role-aware, the service</span></div>\n<div class=\"c-line\" data-line=\"384\"><span class=\"c-no\">384</span><span class=\"c-src\">        method&<span class=\"c-com\">#x27;s sole responsibility is to run per-member</span></span></div>\n<div class=\"c-line\" data-line=\"385\"><span class=\"c-no\">385</span><span class=\"c-src\">        ``cancel + bus purge`` (storage cannot touch the bus) via the</span></div>\n<div class=\"c-line\" data-line=\"386\"><span class=\"c-no\">386</span><span class=\"c-src\">        role-appropriate ``delete_agent`` / ``delete_session`` call, <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"387\"><span class=\"c-no\">387</span><span class=\"c-src\">        then delegate to storage <span class=\"c-kw\">for</span> the remaining leader-detach +</span></div>\n<div class=\"c-line\" data-line=\"388\"><span class=\"c-no\">388</span><span class=\"c-src\">        team-record cleanup.</span></div>\n<div class=\"c-line\" data-line=\"389\"><span class=\"c-no\">389</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"390\"><span class=\"c-no\">390</span><span class=\"c-src\">        Branches per member role:</span></div>\n<div class=\"c-line\" data-line=\"391\"><span class=\"c-no\">391</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"392\"><span class=\"c-no\">392</span><span class=\"c-src\">        - ``role == <span class=\"c-str\">&quot;created&quot;</span>``: the member was spawned by ``AgentCreate``</span></div>\n<div class=\"c-line\" data-line=\"393\"><span class=\"c-no\">393</span><span class=\"c-src\">          <span class=\"c-kw\">and</span> lives only <span class=\"c-kw\">as</span> long <span class=\"c-kw\">as</span> the team — delegate to</span></div>\n<div class=\"c-line\" data-line=\"394\"><span class=\"c-no\">394</span><span class=\"c-src\">          :meth:`delete_agent` so its record, session, <span class=\"c-kw\">and</span> bus state</span></div>\n<div class=\"c-line\" data-line=\"395\"><span class=\"c-no\">395</span><span class=\"c-src\">          are fully removed.</span></div>\n<div class=\"c-line\" data-line=\"396\"><span class=\"c-no\">396</span><span class=\"c-src\">        - ``role == <span class=\"c-str\">&quot;invited&quot;</span>``: the member <span class=\"c-kw\">is</span> a pre-existing user-owned</span></div>\n<div class=\"c-line\" data-line=\"397\"><span class=\"c-no\">397</span><span class=\"c-src\">          agent borrowed via ``AgentInvite``. Only the borrowed</span></div>\n<div class=\"c-line\" data-line=\"398\"><span class=\"c-no\">398</span><span class=\"c-src\">          team-scoped session <span class=\"c-kw\">is</span> removed; the underlying</span></div>\n<div class=\"c-line\" data-line=\"399\"><span class=\"c-no\">399</span><span class=\"c-src\">          :<span class=\"c-kw\">class</span>:`AgentRecord` <span class=\"c-kw\">and</span> its other sessions survive.</span></div>\n<div class=\"c-line\" data-line=\"400\"><span class=\"c-no\">400</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"401\"><span class=\"c-no\">401</span><span class=\"c-src\">        The leader&<span class=\"c-com\">#x27;s own session is **not** deleted — teams dissolve,</span></span></div>\n<div class=\"c-line\" data-line=\"402\"><span class=\"c-no\">402</span><span class=\"c-src\">        leaders survive (<span class=\"c-kw\">and</span> have their ``team_id`` cleared by</span></div>\n<div class=\"c-line\" data-line=\"403\"><span class=\"c-no\">403</span><span class=\"c-src\">        ``storage.delete_team``).</span></div>\n<div class=\"c-line\" data-line=\"404\"><span class=\"c-no\">404</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"405\"><span class=\"c-no\">405</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"406\"><span class=\"c-no\">406</span><span class=\"c-src\">            user_id (`str`): The owner user id.</span></div>\n<div class=\"c-line\" data-line=\"407\"><span class=\"c-no\">407</span><span class=\"c-src\">            team_id (`str`): The team to dissolve.</span></div>\n<div class=\"c-line\" data-line=\"408\"><span class=\"c-no\">408</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"409\"><span class=\"c-no\">409</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"410\"><span class=\"c-no\">410</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"411\"><span class=\"c-no\">411</span><span class=\"c-src\">                ``<span class=\"c-kw\">True</span>`` <span class=\"c-kw\">if</span> the team record existed <span class=\"c-kw\">and</span> was deleted.</span></div>\n<div class=\"c-line\" data-line=\"412\"><span class=\"c-no\">412</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"413\"><span class=\"c-no\">413</span><span class=\"c-src\">        team = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.get_team(user_id, team_id)</span></div>\n<div class=\"c-line\" data-line=\"414\"><span class=\"c-no\">414</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> team <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"415\"><span class=\"c-no\">415</span><span class=\"c-src\">            <span class=\"c-com\"># Still call storage.delete_team so it can clean any index</span></span></div>\n<div class=\"c-line\" data-line=\"416\"><span class=\"c-no\">416</span><span class=\"c-src\">            <span class=\"c-com\"># residue, but the return value will be False.</span></span></div>\n<div class=\"c-line\" data-line=\"417\"><span class=\"c-no\">417</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.delete_team(user_id, team_id)</span></div>\n<div class=\"c-line\" data-line=\"418\"><span class=\"c-no\">418</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"419\"><span class=\"c-no\">419</span><span class=\"c-src\">        members = <span class=\"c-kw\">await</span> _ensure_team_members(<span class=\"c-kw\">self</span>._storage, user_id, team)</span></div>\n<div class=\"c-line\" data-line=\"420\"><span class=\"c-no\">420</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> member <span class=\"c-kw\">in</span> members:</span></div>\n<div class=\"c-line\" data-line=\"421\"><span class=\"c-no\">421</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> member.role == <span class=\"c-str\">&quot;created&quot;</span>:</span></div>\n<div class=\"c-line\" data-line=\"422\"><span class=\"c-no\">422</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.delete_agent(member.owner_id, member.agent_id)</span></div>\n<div class=\"c-line\" data-line=\"423\"><span class=\"c-no\">423</span><span class=\"c-src\">            <span class=\"c-kw\">else</span>:  <span class=\"c-com\"># invited</span></span></div>\n<div class=\"c-line\" data-line=\"424\"><span class=\"c-no\">424</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.delete_session(</span></div>\n<div class=\"c-line\" data-line=\"425\"><span class=\"c-no\">425</span><span class=\"c-src\">                    member.owner_id,</span></div>\n<div class=\"c-line\" data-line=\"426\"><span class=\"c-no\">426</span><span class=\"c-src\">                    member.agent_id,</span></div>\n<div class=\"c-line\" data-line=\"427\"><span class=\"c-no\">427</span><span class=\"c-src\">                    member.session_id,</span></div>\n<div class=\"c-line\" data-line=\"428\"><span class=\"c-no\">428</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"429\"><span class=\"c-no\">429</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"430\"><span class=\"c-no\">430</span><span class=\"c-src\">        <span class=\"c-com\"># storage.delete_team walks the same members again to run its</span></span></div>\n<div class=\"c-line\" data-line=\"431\"><span class=\"c-no\">431</span><span class=\"c-src\">        <span class=\"c-com\"># own role-aware cascade — those calls are now idempotent</span></span></div>\n<div class=\"c-line\" data-line=\"432\"><span class=\"c-no\">432</span><span class=\"c-src\">        <span class=\"c-com\"># no-ops (records already removed above). What remains for</span></span></div>\n<div class=\"c-line\" data-line=\"433\"><span class=\"c-no\">433</span><span class=\"c-src\">        <span class=\"c-com\"># storage is leader-detach + team-record + index cleanup.</span></span></div>\n<div class=\"c-line\" data-line=\"434\"><span class=\"c-no\">434</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.delete_team(user_id, team_id)</span></div>\n<div class=\"c-line\" data-line=\"435\"><span class=\"c-no\">435</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"436\"><span class=\"c-no\">436</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> delete_agent(<span class=\"c-kw\">self</span>, user_id: str, agent_id: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"437\"><span class=\"c-no\">437</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Cancel, delete <span class=\"c-kw\">and</span> bus-purge every session <span class=\"c-kw\">and</span> schedule</span></div>\n<div class=\"c-line\" data-line=\"438\"><span class=\"c-no\">438</span><span class=\"c-src\">        owned by an agent, then drop the agent record.</span></div>\n<div class=\"c-line\" data-line=\"439\"><span class=\"c-no\">439</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"440\"><span class=\"c-no\">440</span><span class=\"c-src\">        Delegates per-session work to :meth:`delete_session` <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"441\"><span class=\"c-no\">441</span><span class=\"c-src\">        per-schedule work to :meth:`delete_schedule`, then asks</span></div>\n<div class=\"c-line\" data-line=\"442\"><span class=\"c-no\">442</span><span class=\"c-src\">        storage to clean the remaining agent-scoped state (the agent</span></div>\n<div class=\"c-line\" data-line=\"443\"><span class=\"c-no\">443</span><span class=\"c-src\">        record, the agent index entry, <span class=\"c-kw\">and</span> any team back-references).</span></div>\n<div class=\"c-line\" data-line=\"444\"><span class=\"c-no\">444</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"445\"><span class=\"c-no\">445</span><span class=\"c-src\">        **Reverse-cascade <span class=\"c-kw\">for</span> invited members.** When an agent <span class=\"c-kw\">is</span></span></div>\n<div class=\"c-line\" data-line=\"446\"><span class=\"c-no\">446</span><span class=\"c-src\">        borrowed into a team (``AgentInvite``), it has a session <span class=\"c-kw\">with</span></span></div>\n<div class=\"c-line\" data-line=\"447\"><span class=\"c-no\">447</span><span class=\"c-src\">        ``team_id`` set that it does <span class=\"c-kw\">not</span> lead. Deleting the agent <span class=\"c-kw\">while</span></span></div>\n<div class=\"c-line\" data-line=\"448\"><span class=\"c-no\">448</span><span class=\"c-src\">        such a borrowed session exists would leave a stale</span></div>\n<div class=\"c-line\" data-line=\"449\"><span class=\"c-no\">449</span><span class=\"c-src\">        :<span class=\"c-kw\">class</span>:`TeamMember` entry behind, <span class=\"c-kw\">and</span> — worse — trigger the</span></div>\n<div class=\"c-line\" data-line=\"450\"><span class=\"c-no\">450</span><span class=\"c-src\">        storage cascade <span class=\"c-kw\">in</span> that team&<span class=\"c-com\">#x27;s next ``delete_team``, which</span></span></div>\n<div class=\"c-line\" data-line=\"451\"><span class=\"c-no\">451</span><span class=\"c-src\">        iterates the team roster (via ``_ensure_team_members``) <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"452\"><span class=\"c-no\">452</span><span class=\"c-src\">        would <span class=\"c-kw\">try</span> to re-delete this already-gone agent. So before</span></div>\n<div class=\"c-line\" data-line=\"453\"><span class=\"c-no\">453</span><span class=\"c-src\">        deleting each session, this method extracts the corresponding</span></div>\n<div class=\"c-line\" data-line=\"454\"><span class=\"c-no\">454</span><span class=\"c-src\">        entry <span class=\"c-kw\">from</span> the borrowing team&<span class=\"c-com\">#x27;s roster (matched by</span></span></div>\n<div class=\"c-line\" data-line=\"455\"><span class=\"c-no\">455</span><span class=\"c-src\">        ``session_id``, <span class=\"c-kw\">not</span> ``agent_id``, so a leader session that</span></div>\n<div class=\"c-line\" data-line=\"456\"><span class=\"c-no\">456</span><span class=\"c-src\">        happens to share the agent id — impossible today but cheap to</span></div>\n<div class=\"c-line\" data-line=\"457\"><span class=\"c-no\">457</span><span class=\"c-src\">        be careful about — <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> touched).</span></div>\n<div class=\"c-line\" data-line=\"458\"><span class=\"c-no\">458</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"459\"><span class=\"c-no\">459</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"460\"><span class=\"c-no\">460</span><span class=\"c-src\">            user_id (`str`): The owner user id.</span></div>\n<div class=\"c-line\" data-line=\"461\"><span class=\"c-no\">461</span><span class=\"c-src\">            agent_id (`str`): The agent to delete.</span></div>\n<div class=\"c-line\" data-line=\"462\"><span class=\"c-no\">462</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"463\"><span class=\"c-no\">463</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"464\"><span class=\"c-no\">464</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"465\"><span class=\"c-no\">465</span><span class=\"c-src\">                ``<span class=\"c-kw\">True</span>`` <span class=\"c-kw\">if</span> the agent record existed <span class=\"c-kw\">and</span> was deleted.</span></div>\n<div class=\"c-line\" data-line=\"466\"><span class=\"c-no\">466</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"467\"><span class=\"c-no\">467</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> session <span class=\"c-kw\">in</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.list_sessions(user_id, agent_id):</span></div>\n<div class=\"c-line\" data-line=\"468\"><span class=\"c-no\">468</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> session.team_id <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"469\"><span class=\"c-no\">469</span><span class=\"c-src\">                team = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.get_team(</span></div>\n<div class=\"c-line\" data-line=\"470\"><span class=\"c-no\">470</span><span class=\"c-src\">                    user_id,</span></div>\n<div class=\"c-line\" data-line=\"471\"><span class=\"c-no\">471</span><span class=\"c-src\">                    session.team_id,</span></div>\n<div class=\"c-line\" data-line=\"472\"><span class=\"c-no\">472</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"473\"><span class=\"c-no\">473</span><span class=\"c-src\">                <span class=\"c-com\"># Only worker sessions require the extraction — a leader</span></span></div>\n<div class=\"c-line\" data-line=\"474\"><span class=\"c-no\">474</span><span class=\"c-src\">                <span class=\"c-com\"># session dropping its team is handled by</span></span></div>\n<div class=\"c-line\" data-line=\"475\"><span class=\"c-no\">475</span><span class=\"c-src\">                <span class=\"c-com\"># ``storage.delete_session -&gt; delete_team`` further down.</span></span></div>\n<div class=\"c-line\" data-line=\"476\"><span class=\"c-no\">476</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> team <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">and</span> team.session_id != session.id:</span></div>\n<div class=\"c-line\" data-line=\"477\"><span class=\"c-no\">477</span><span class=\"c-src\">                    members = <span class=\"c-kw\">await</span> _ensure_team_members(</span></div>\n<div class=\"c-line\" data-line=\"478\"><span class=\"c-no\">478</span><span class=\"c-src\">                        <span class=\"c-kw\">self</span>._storage,</span></div>\n<div class=\"c-line\" data-line=\"479\"><span class=\"c-no\">479</span><span class=\"c-src\">                        user_id,</span></div>\n<div class=\"c-line\" data-line=\"480\"><span class=\"c-no\">480</span><span class=\"c-src\">                        team,</span></div>\n<div class=\"c-line\" data-line=\"481\"><span class=\"c-no\">481</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"482\"><span class=\"c-no\">482</span><span class=\"c-src\">                    filtered = [</span></div>\n<div class=\"c-line\" data-line=\"483\"><span class=\"c-no\">483</span><span class=\"c-src\">                        m <span class=\"c-kw\">for</span> m <span class=\"c-kw\">in</span> members <span class=\"c-kw\">if</span> m.session_id != session.id</span></div>\n<div class=\"c-line\" data-line=\"484\"><span class=\"c-no\">484</span><span class=\"c-src\">                    ]</span></div>\n<div class=\"c-line\" data-line=\"485\"><span class=\"c-no\">485</span><span class=\"c-src\">                    <span class=\"c-kw\">if</span> len(filtered) != len(members):</span></div>\n<div class=\"c-line\" data-line=\"486\"><span class=\"c-no\">486</span><span class=\"c-src\">                        team.data.members = filtered</span></div>\n<div class=\"c-line\" data-line=\"487\"><span class=\"c-no\">487</span><span class=\"c-src\">                        team.data.member_ids = [</span></div>\n<div class=\"c-line\" data-line=\"488\"><span class=\"c-no\">488</span><span class=\"c-src\">                            mid</span></div>\n<div class=\"c-line\" data-line=\"489\"><span class=\"c-no\">489</span><span class=\"c-src\">                            <span class=\"c-kw\">for</span> mid <span class=\"c-kw\">in</span> team.data.member_ids</span></div>\n<div class=\"c-line\" data-line=\"490\"><span class=\"c-no\">490</span><span class=\"c-src\">                            <span class=\"c-kw\">if</span> mid != agent_id</span></div>\n<div class=\"c-line\" data-line=\"491\"><span class=\"c-no\">491</span><span class=\"c-src\">                        ]</span></div>\n<div class=\"c-line\" data-line=\"492\"><span class=\"c-no\">492</span><span class=\"c-src\">                        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.upsert_team(user_id, team)</span></div>\n<div class=\"c-line\" data-line=\"493\"><span class=\"c-no\">493</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.delete_session(user_id, agent_id, session.id)</span></div>\n<div class=\"c-line\" data-line=\"494\"><span class=\"c-no\">494</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"495\"><span class=\"c-no\">495</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> schedule <span class=\"c-kw\">in</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.list_schedules(user_id):</span></div>\n<div class=\"c-line\" data-line=\"496\"><span class=\"c-no\">496</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> schedule.agent_id == agent_id:</span></div>\n<div class=\"c-line\" data-line=\"497\"><span class=\"c-no\">497</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.delete_schedule(user_id, schedule.id)</span></div>\n<div class=\"c-line\" data-line=\"498\"><span class=\"c-no\">498</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"499\"><span class=\"c-no\">499</span><span class=\"c-src\">        <span class=\"c-com\"># storage.delete_agent re-iterates sessions and schedules —</span></span></div>\n<div class=\"c-line\" data-line=\"500\"><span class=\"c-no\">500</span><span class=\"c-src\">        <span class=\"c-com\"># those re-runs are idempotent no-ops because the records were</span></span></div>\n<div class=\"c-line\" data-line=\"501\"><span class=\"c-no\">501</span><span class=\"c-src\">        <span class=\"c-com\"># already removed above. What remains is the agent record,</span></span></div>\n<div class=\"c-line\" data-line=\"502\"><span class=\"c-no\">502</span><span class=\"c-src\">        <span class=\"c-com\"># the agent index entry, and team back-reference scrubbing.</span></span></div>\n<div class=\"c-line\" data-line=\"503\"><span class=\"c-no\">503</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.delete_agent(user_id, agent_id)</span></div>\n<div class=\"c-line\" data-line=\"504\"><span class=\"c-no\">504</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"505\"><span class=\"c-no\">505</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> delete_schedule(</span></div>\n<div class=\"c-line\" data-line=\"506\"><span class=\"c-no\">506</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"507\"><span class=\"c-no\">507</span><span class=\"c-src\">        user_id: str,</span></div>\n<div class=\"c-line\" data-line=\"508\"><span class=\"c-no\">508</span><span class=\"c-src\">        schedule_id: str,</span></div>\n<div class=\"c-line\" data-line=\"509\"><span class=\"c-no\">509</span><span class=\"c-src\">    ) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"510\"><span class=\"c-no\">510</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Cancel, delete <span class=\"c-kw\">and</span> bus-purge every session spawned by a</span></div>\n<div class=\"c-line\" data-line=\"511\"><span class=\"c-no\">511</span><span class=\"c-src\">        schedule, then drop the schedule record.</span></div>\n<div class=\"c-line\" data-line=\"512\"><span class=\"c-no\">512</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"513\"><span class=\"c-no\">513</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"514\"><span class=\"c-no\">514</span><span class=\"c-src\">            user_id (`str`): The owner user id.</span></div>\n<div class=\"c-line\" data-line=\"515\"><span class=\"c-no\">515</span><span class=\"c-src\">            schedule_id (`str`): The schedule to delete.</span></div>\n<div class=\"c-line\" data-line=\"516\"><span class=\"c-no\">516</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"517\"><span class=\"c-no\">517</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"518\"><span class=\"c-no\">518</span><span class=\"c-src\">            `bool`:</span></div>\n<div class=\"c-line\" data-line=\"519\"><span class=\"c-no\">519</span><span class=\"c-src\">                ``<span class=\"c-kw\">True</span>`` <span class=\"c-kw\">if</span> the schedule record existed <span class=\"c-kw\">and</span> was deleted.</span></div>\n<div class=\"c-line\" data-line=\"520\"><span class=\"c-no\">520</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"521\"><span class=\"c-no\">521</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> session <span class=\"c-kw\">in</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.list_sessions_by_schedule(</span></div>\n<div class=\"c-line\" data-line=\"522\"><span class=\"c-no\">522</span><span class=\"c-src\">            user_id,</span></div>\n<div class=\"c-line\" data-line=\"523\"><span class=\"c-no\">523</span><span class=\"c-src\">            schedule_id,</span></div>\n<div class=\"c-line\" data-line=\"524\"><span class=\"c-no\">524</span><span class=\"c-src\">        ):</span></div>\n<div class=\"c-line\" data-line=\"525\"><span class=\"c-no\">525</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.delete_session(</span></div>\n<div class=\"c-line\" data-line=\"526\"><span class=\"c-no\">526</span><span class=\"c-src\">                user_id,</span></div>\n<div class=\"c-line\" data-line=\"527\"><span class=\"c-no\">527</span><span class=\"c-src\">                session.agent_id,</span></div>\n<div class=\"c-line\" data-line=\"528\"><span class=\"c-no\">528</span><span class=\"c-src\">                session.id,</span></div>\n<div class=\"c-line\" data-line=\"529\"><span class=\"c-no\">529</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"530\"><span class=\"c-no\">530</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"531\"><span class=\"c-no\">531</span><span class=\"c-src\">        <span class=\"c-com\"># storage.delete_schedule re-iterates the same sessions —</span></span></div>\n<div class=\"c-line\" data-line=\"532\"><span class=\"c-no\">532</span><span class=\"c-src\">        <span class=\"c-com\"># idempotent no-ops; only schedule record + indexes remain.</span></span></div>\n<div class=\"c-line\" data-line=\"533\"><span class=\"c-no\">533</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.delete_schedule(user_id, schedule_id)</span></div>\n<div class=\"c-line\" data-line=\"534\"><span class=\"c-no\">534</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"535\"><span class=\"c-no\">535</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"536\"><span class=\"c-no\">536</span><span class=\"c-src\">    <span class=\"c-com\"># Internals</span></span></div>\n<div class=\"c-line\" data-line=\"537\"><span class=\"c-no\">537</span><span class=\"c-src\">    <span class=\"c-com\"># ------------------------------------------------------------------</span></span></div>\n<div class=\"c-line\" data-line=\"538\"><span class=\"c-no\">538</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"539\"><span class=\"c-no\">539</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _team_worker_session_ids(</span></div>\n<div class=\"c-line\" data-line=\"540\"><span class=\"c-no\">540</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"541\"><span class=\"c-no\">541</span><span class=\"c-src\">        user_id: str,</span></div>\n<div class=\"c-line\" data-line=\"542\"><span class=\"c-no\">542</span><span class=\"c-src\">        agent_id: str,</span></div>\n<div class=\"c-line\" data-line=\"543\"><span class=\"c-no\">543</span><span class=\"c-src\">        session_id: str,</span></div>\n<div class=\"c-line\" data-line=\"544\"><span class=\"c-no\">544</span><span class=\"c-src\">    ) -&gt; list[str]:</span></div>\n<div class=\"c-line\" data-line=\"545\"><span class=\"c-no\">545</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Return the session ids of every worker <span class=\"c-kw\">in</span> the team that</span></div>\n<div class=\"c-line\" data-line=\"546\"><span class=\"c-no\">546</span><span class=\"c-src\">        ``session_id`` leads, <span class=\"c-kw\">or</span> ``[]`` when the session does <span class=\"c-kw\">not</span> lead</span></div>\n<div class=\"c-line\" data-line=\"547\"><span class=\"c-no\">547</span><span class=\"c-src\">        a team.</span></div>\n<div class=\"c-line\" data-line=\"548\"><span class=\"c-no\">548</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"549\"><span class=\"c-no\">549</span><span class=\"c-src\">        Mirrors :meth:`StorageBase.delete_session`&<span class=\"c-com\">#x27;s own team-leader</span></span></div>\n<div class=\"c-line\" data-line=\"550\"><span class=\"c-no\">550</span><span class=\"c-src\">        cascade so the bus side can purge the same sessions.</span></div>\n<div class=\"c-line\" data-line=\"551\"><span class=\"c-no\">551</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"552\"><span class=\"c-no\">552</span><span class=\"c-src\">        Uses :func:`ensure_team_members` — which carries the exact</span></div>\n<div class=\"c-line\" data-line=\"553\"><span class=\"c-no\">553</span><span class=\"c-src\">        session id per member (including invited members whose agent</span></div>\n<div class=\"c-line\" data-line=\"554\"><span class=\"c-no\">554</span><span class=\"c-src\">        can have multiple sessions of its own, only one of which</span></div>\n<div class=\"c-line\" data-line=\"555\"><span class=\"c-no\">555</span><span class=\"c-src\">        belongs to this team). Falling back to</span></div>\n<div class=\"c-line\" data-line=\"556\"><span class=\"c-no\">556</span><span class=\"c-src\">        ``list_sessions(agent_id)[0]`` here would pick the wrong</span></div>\n<div class=\"c-line\" data-line=\"557\"><span class=\"c-no\">557</span><span class=\"c-src\">        session <span class=\"c-kw\">for</span> invited agents.</span></div>\n<div class=\"c-line\" data-line=\"558\"><span class=\"c-no\">558</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"559\"><span class=\"c-no\">559</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"560\"><span class=\"c-no\">560</span><span class=\"c-src\">            user_id (`str`): The owner user id.</span></div>\n<div class=\"c-line\" data-line=\"561\"><span class=\"c-no\">561</span><span class=\"c-src\">            agent_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"562\"><span class=\"c-no\">562</span><span class=\"c-src\">                The agent that owns ``session_id``. May be empty when</span></div>\n<div class=\"c-line\" data-line=\"563\"><span class=\"c-no\">563</span><span class=\"c-src\">                unknown; team-leader lookup does <span class=\"c-kw\">not</span> depend on it.</span></div>\n<div class=\"c-line\" data-line=\"564\"><span class=\"c-no\">564</span><span class=\"c-src\">            session_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"565\"><span class=\"c-no\">565</span><span class=\"c-src\">                The candidate leader session.</span></div>\n<div class=\"c-line\" data-line=\"566\"><span class=\"c-no\">566</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"567\"><span class=\"c-no\">567</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"568\"><span class=\"c-no\">568</span><span class=\"c-src\">            `list[str]`:</span></div>\n<div class=\"c-line\" data-line=\"569\"><span class=\"c-no\">569</span><span class=\"c-src\">                Worker session ids, empty when this session <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> a</span></div>\n<div class=\"c-line\" data-line=\"570\"><span class=\"c-no\">570</span><span class=\"c-src\">                team leader.</span></div>\n<div class=\"c-line\" data-line=\"571\"><span class=\"c-no\">571</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"572\"><span class=\"c-no\">572</span><span class=\"c-src\">        session = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.get_session(</span></div>\n<div class=\"c-line\" data-line=\"573\"><span class=\"c-no\">573</span><span class=\"c-src\">            user_id,</span></div>\n<div class=\"c-line\" data-line=\"574\"><span class=\"c-no\">574</span><span class=\"c-src\">            agent_id,</span></div>\n<div class=\"c-line\" data-line=\"575\"><span class=\"c-no\">575</span><span class=\"c-src\">            session_id,</span></div>\n<div class=\"c-line\" data-line=\"576\"><span class=\"c-no\">576</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"577\"><span class=\"c-no\">577</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> session <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">or</span> <span class=\"c-kw\">not</span> session.team_id:</span></div>\n<div class=\"c-line\" data-line=\"578\"><span class=\"c-no\">578</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> []</span></div>\n<div class=\"c-line\" data-line=\"579\"><span class=\"c-no\">579</span><span class=\"c-src\">        team = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.get_team(user_id, session.team_id)</span></div>\n<div class=\"c-line\" data-line=\"580\"><span class=\"c-no\">580</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> team <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">or</span> team.session_id != session_id:</span></div>\n<div class=\"c-line\" data-line=\"581\"><span class=\"c-no\">581</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> []</span></div>\n<div class=\"c-line\" data-line=\"582\"><span class=\"c-no\">582</span><span class=\"c-src\">        members = <span class=\"c-kw\">await</span> _ensure_team_members(<span class=\"c-kw\">self</span>._storage, user_id, team)</span></div>\n<div class=\"c-line\" data-line=\"583\"><span class=\"c-no\">583</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> [m.session_id <span class=\"c-kw\">for</span> m <span class=\"c-kw\">in</span> members]</span></div>\n<div class=\"c-line\" data-line=\"584\"><span class=\"c-no\">584</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"585\"><span class=\"c-no\">585</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _cancel_runs(<span class=\"c-kw\">self</span>, session_ids: list[str]) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"586\"><span class=\"c-no\">586</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Cancel every <span class=\"c-kw\">in</span>-flight run <span class=\"c-kw\">in</span> ``session_ids`` concurrently.</span></div>\n<div class=\"c-line\" data-line=\"587\"><span class=\"c-no\">587</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"588\"><span class=\"c-no\">588</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"589\"><span class=\"c-no\">589</span><span class=\"c-src\">            session_ids (`list[str]`):</span></div>\n<div class=\"c-line\" data-line=\"590\"><span class=\"c-no\">590</span><span class=\"c-src\">                Sessions whose runs should be cancelled.</span></div>\n<div class=\"c-line\" data-line=\"591\"><span class=\"c-no\">591</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"592\"><span class=\"c-no\">592</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> session_ids:</span></div>\n<div class=\"c-line\" data-line=\"593\"><span class=\"c-no\">593</span><span class=\"c-src\">            <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"594\"><span class=\"c-no\">594</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> asyncio.gather(</span></div>\n<div class=\"c-line\" data-line=\"595\"><span class=\"c-no\">595</span><span class=\"c-src\">            *(<span class=\"c-kw\">self</span>.cancel_session_run(sid) <span class=\"c-kw\">for</span> sid <span class=\"c-kw\">in</span> session_ids),</span></div>\n<div class=\"c-line\" data-line=\"596\"><span class=\"c-no\">596</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"597\"><span class=\"c-no\">597</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"598\"><span class=\"c-no\">598</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _purge_bus(<span class=\"c-kw\">self</span>, session_ids: list[str]) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"599\"><span class=\"c-no\">599</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Drop bus state (events log + inbox) <span class=\"c-kw\">for</span> each id concurrently.</span></div>\n<div class=\"c-line\" data-line=\"600\"><span class=\"c-no\">600</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"601\"><span class=\"c-no\">601</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"602\"><span class=\"c-no\">602</span><span class=\"c-src\">            session_ids (`list[str]`):</span></div>\n<div class=\"c-line\" data-line=\"603\"><span class=\"c-no\">603</span><span class=\"c-src\">                Sessions whose bus state should be purged.</span></div>\n<div class=\"c-line\" data-line=\"604\"><span class=\"c-no\">604</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"605\"><span class=\"c-no\">605</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> session_ids:</span></div>\n<div class=\"c-line\" data-line=\"606\"><span class=\"c-no\">606</span><span class=\"c-src\">            <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"607\"><span class=\"c-no\">607</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> asyncio.gather(</span></div>\n<div class=\"c-line\" data-line=\"608\"><span class=\"c-no\">608</span><span class=\"c-src\">            *(<span class=\"c-kw\">self</span>._purge_session_bus(sid) <span class=\"c-kw\">for</span> sid <span class=\"c-kw\">in</span> session_ids),</span></div>\n<div class=\"c-line\" data-line=\"609\"><span class=\"c-no\">609</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"610\"><span class=\"c-no\">610</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"611\"><span class=\"c-no\">611</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _purge_session_bus(<span class=\"c-kw\">self</span>, session_id: str) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"612\"><span class=\"c-no\">612</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Drop all per-session bus state for one session.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"613\"><span class=\"c-no\">613</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._bus.log_trim(</span></div>\n<div class=\"c-line\" data-line=\"614\"><span class=\"c-no\">614</span><span class=\"c-src\">            MessageBusKeys.session_events(session_id),</span></div>\n<div class=\"c-line\" data-line=\"615\"><span class=\"c-no\">615</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"616\"><span class=\"c-no\">616</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._bus.queue_delete(</span></div>\n<div class=\"c-line\" data-line=\"617\"><span class=\"c-no\">617</span><span class=\"c-src\">            MessageBusKeys.inbox(session_id),</span></div>\n<div class=\"c-line\" data-line=\"618\"><span class=\"c-no\">618</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"619\"><span class=\"c-no\">619</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._bus.registry_drop(</span></div>\n<div class=\"c-line\" data-line=\"620\"><span class=\"c-no\">620</span><span class=\"c-src\">            MessageBusKeys.bg_tasks(session_id),</span></div>\n<div class=\"c-line\" data-line=\"621\"><span class=\"c-no\">621</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"622\"><span class=\"c-no\">622</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"623\"><span class=\"c-no\">623</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _purge_subagent_hitl(</span></div>\n<div class=\"c-line\" data-line=\"624\"><span class=\"c-no\">624</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"625\"><span class=\"c-no\">625</span><span class=\"c-src\">        user_id: str,</span></div>\n<div class=\"c-line\" data-line=\"626\"><span class=\"c-no\">626</span><span class=\"c-src\">        agent_id: str,</span></div>\n<div class=\"c-line\" data-line=\"627\"><span class=\"c-no\">627</span><span class=\"c-src\">        session_id: str,</span></div>\n<div class=\"c-line\" data-line=\"628\"><span class=\"c-no\">628</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"629\"><span class=\"c-no\">629</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Clean leader-side subagent HITL projections <span class=\"c-kw\">for</span> a session</span></div>\n<div class=\"c-line\" data-line=\"630\"><span class=\"c-no\">630</span><span class=\"c-src\">        about to be deleted (design §3.7).</span></div>\n<div class=\"c-line\" data-line=\"631\"><span class=\"c-no\">631</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"632\"><span class=\"c-no\">632</span><span class=\"c-src\">        Two cases, resolved <span class=\"c-kw\">from</span> the session&<span class=\"c-com\">#x27;s role:</span></span></div>\n<div class=\"c-line\" data-line=\"633\"><span class=\"c-no\">633</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"634\"><span class=\"c-no\">634</span><span class=\"c-src\">        - **Leader session** (it leads a team): purge the entire hash</span></div>\n<div class=\"c-line\" data-line=\"635\"><span class=\"c-no\">635</span><span class=\"c-src\">          keyed by this session — every projected member card goes.</span></div>\n<div class=\"c-line\" data-line=\"636\"><span class=\"c-no\">636</span><span class=\"c-src\">        - **Worker session** (it has a ``team_id`` but <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> the</span></div>\n<div class=\"c-line\" data-line=\"637\"><span class=\"c-no\">637</span><span class=\"c-src\">          leader): drop just this worker<span class=\"c-str\">&#x27;s entries from the *leader&#x27;</span>s*</span></div>\n<div class=\"c-line\" data-line=\"638\"><span class=\"c-no\">638</span><span class=\"c-src\">          hash, leaving sibling members&<span class=\"c-com\">#x27; cards intact.</span></span></div>\n<div class=\"c-line\" data-line=\"639\"><span class=\"c-no\">639</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"640\"><span class=\"c-no\">640</span><span class=\"c-src\">        Must run before storage cascades remove the team / session</span></div>\n<div class=\"c-line\" data-line=\"641\"><span class=\"c-no\">641</span><span class=\"c-src\">        records this resolution depends on. Failures are swallowed — a</span></div>\n<div class=\"c-line\" data-line=\"642\"><span class=\"c-no\">642</span><span class=\"c-src\">        stale projection <span class=\"c-kw\">is</span> <span class=\"c-kw\">self</span>-healed by reconcile-on-read <span class=\"c-kw\">and</span> must</span></div>\n<div class=\"c-line\" data-line=\"643\"><span class=\"c-no\">643</span><span class=\"c-src\">        <span class=\"c-kw\">not</span> block the delete cascade.</span></div>\n<div class=\"c-line\" data-line=\"644\"><span class=\"c-no\">644</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"645\"><span class=\"c-no\">645</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"646\"><span class=\"c-no\">646</span><span class=\"c-src\">            user_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"647\"><span class=\"c-no\">647</span><span class=\"c-src\">                The owner user id.</span></div>\n<div class=\"c-line\" data-line=\"648\"><span class=\"c-no\">648</span><span class=\"c-src\">            agent_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"649\"><span class=\"c-no\">649</span><span class=\"c-src\">                The agent that owns ``session_id``.</span></div>\n<div class=\"c-line\" data-line=\"650\"><span class=\"c-no\">650</span><span class=\"c-src\">            session_id (`str`):</span></div>\n<div class=\"c-line\" data-line=\"651\"><span class=\"c-no\">651</span><span class=\"c-src\">                The session being deleted.</span></div>\n<div class=\"c-line\" data-line=\"652\"><span class=\"c-no\">652</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"653\"><span class=\"c-no\">653</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"654\"><span class=\"c-no\">654</span><span class=\"c-src\">            session = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.get_session(</span></div>\n<div class=\"c-line\" data-line=\"655\"><span class=\"c-no\">655</span><span class=\"c-src\">                user_id,</span></div>\n<div class=\"c-line\" data-line=\"656\"><span class=\"c-no\">656</span><span class=\"c-src\">                agent_id,</span></div>\n<div class=\"c-line\" data-line=\"657\"><span class=\"c-no\">657</span><span class=\"c-src\">                session_id,</span></div>\n<div class=\"c-line\" data-line=\"658\"><span class=\"c-no\">658</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"659\"><span class=\"c-no\">659</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> session <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span> <span class=\"c-kw\">or</span> <span class=\"c-kw\">not</span> session.team_id:</span></div>\n<div class=\"c-line\" data-line=\"660\"><span class=\"c-no\">660</span><span class=\"c-src\">                <span class=\"c-com\"># Not in a team — also clear any hash that may have been</span></span></div>\n<div class=\"c-line\" data-line=\"661\"><span class=\"c-no\">661</span><span class=\"c-src\">                <span class=\"c-com\"># created with this session as a (future) leader key.</span></span></div>\n<div class=\"c-line\" data-line=\"662\"><span class=\"c-no\">662</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> SubagentHitlProjector.purge(<span class=\"c-kw\">self</span>._projection, session_id)</span></div>\n<div class=\"c-line\" data-line=\"663\"><span class=\"c-no\">663</span><span class=\"c-src\">                <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"664\"><span class=\"c-no\">664</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"665\"><span class=\"c-no\">665</span><span class=\"c-src\">            team = <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._storage.get_team(user_id, session.team_id)</span></div>\n<div class=\"c-line\" data-line=\"666\"><span class=\"c-no\">666</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> team <span class=\"c-kw\">is</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"667\"><span class=\"c-no\">667</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> SubagentHitlProjector.purge(<span class=\"c-kw\">self</span>._projection, session_id)</span></div>\n<div class=\"c-line\" data-line=\"668\"><span class=\"c-no\">668</span><span class=\"c-src\">                <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"669\"><span class=\"c-no\">669</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"670\"><span class=\"c-no\">670</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> team.session_id == session_id:</span></div>\n<div class=\"c-line\" data-line=\"671\"><span class=\"c-no\">671</span><span class=\"c-src\">                <span class=\"c-com\"># Leader session — drop the whole projection store.</span></span></div>\n<div class=\"c-line\" data-line=\"672\"><span class=\"c-no\">672</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> SubagentHitlProjector.purge(<span class=\"c-kw\">self</span>._projection, session_id)</span></div>\n<div class=\"c-line\" data-line=\"673\"><span class=\"c-no\">673</span><span class=\"c-src\">            <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"674\"><span class=\"c-no\">674</span><span class=\"c-src\">                <span class=\"c-com\"># Worker session — drop only its entries from the</span></span></div>\n<div class=\"c-line\" data-line=\"675\"><span class=\"c-no\">675</span><span class=\"c-src\">                <span class=\"c-com\"># leader&#x27;s store.</span></span></div>\n<div class=\"c-line\" data-line=\"676\"><span class=\"c-no\">676</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> SubagentHitlProjector.drop_worker(</span></div>\n<div class=\"c-line\" data-line=\"677\"><span class=\"c-no\">677</span><span class=\"c-src\">                    <span class=\"c-kw\">self</span>._projection,</span></div>\n<div class=\"c-line\" data-line=\"678\"><span class=\"c-no\">678</span><span class=\"c-src\">                    team.session_id,</span></div>\n<div class=\"c-line\" data-line=\"679\"><span class=\"c-no\">679</span><span class=\"c-src\">                    session_id,</span></div>\n<div class=\"c-line\" data-line=\"680\"><span class=\"c-no\">680</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"681\"><span class=\"c-no\">681</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:  <span class=\"c-com\"># pylint: disable=broad-except</span></span></div>\n<div class=\"c-line\" data-line=\"682\"><span class=\"c-no\">682</span><span class=\"c-src\">            logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"683\"><span class=\"c-no\">683</span><span class=\"c-src\">                <span class=\"c-str\">&quot;Failed to purge subagent HITL projection for session &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"684\"><span class=\"c-no\">684</span><span class=\"c-src\">                <span class=\"c-str\">&quot;%s: %s&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"685\"><span class=\"c-no\">685</span><span class=\"c-src\">                session_id,</span></div>\n<div class=\"c-line\" data-line=\"686\"><span class=\"c-no\">686</span><span class=\"c-src\">                str(e),</span></div>\n<div class=\"c-line\" data-line=\"687\"><span class=\"c-no\">687</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"688\"><span class=\"c-no\">688</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 688, "explanation": "SessionService 管多租户多会话，SessionStatus 状态机，支持 cancel/delete/团队级联清理。存储用 Redis。SSE 长连接在 _router/_session.py 的 GET /sessions/{sid}/stream，推 AgentEvent+心跳，符合 ag-ui-protocol。", "knowledge_points": [{"title": "多 Agent 编排", "body": "服务层 Team 工具（TeamCreate/AgentCreate/TeamSay）+ MessageBus（InMemory/Redis）；Leader 动态调度 Worker；非 1.0 代码 pipeline；MultiAgentManager 管生命周期零停机重载。"}], "related_docs": ["README", "W08-RAG与多Agent-Team与服务化", "W12-多Agent协作平台实战(下)-毕业交付", "02-消息与编排"]};
